'use strict';
let scenariosData,scenarioIndex=0,scenarioFocus='all',scenarioQuery='',scenarioSector='',recognitionGap=0,recognitionWindow='both';
const currentScenario=()=>scenariosData.scenarios[scenarioIndex];
function scenarioRating(c,i=scenarioIndex){return scenariosData.profiles[c.ticker].scores[i]}
function ratingLabel(n){return scenariosData.ratingLabels[String(n)]}
function ratingMarkup(n){return `<span class="rating r${n<0?'neg':n>0?'pos':'zero'}" aria-label="${esc(ratingLabel(n))}, rating ${n}"><b>${n>0?'+':''}${n}</b> ${esc(ratingLabel(n))}</span>`}
function passesFinancialGate(c){return !c.stale&&c.revenueGrowth!=null&&c.revenueGrowth>=10&&val(c,'net')>0&&val(c,'fcf')>0}
function hiddenInScenario(c,i=scenarioIndex){return scenarioRating(c,i)>=2&&passesFinancialGate(c)&&c.market&&c.market.excess<recognitionGap&&(recognitionWindow==='recent'||c.market.boomComparable&&c.market.boomExcess<0)}
function hiddenFailures(c,i=scenarioIndex){const reasons=[];if(scenarioRating(c,i)<2)reasons.push('Scenario advantage below +2');if(c.stale)reasons.push('Older reporting period');if(c.revenueGrowth==null)reasons.push('Revenue growth unavailable');else if(c.revenueGrowth<10)reasons.push('Revenue growth below 10%');if(val(c,'net')==null)reasons.push('Profit unavailable');else if(val(c,'net')<=0)reasons.push('No positive net profit');if(val(c,'fcf')==null)reasons.push('FCF unavailable');else if(val(c,'fcf')<=0)reasons.push('No positive FCF');if(!c.market)reasons.push('Stock comparison unavailable');else if(c.market.excess>=recognitionGap)reasons.push(`Not ${recognitionGap<0?'more than '+Math.abs(recognitionGap)+' pp ':''}behind benchmark`);if(recognitionWindow==='both'){if(!c.market?.boomComparable)reasons.push('Comparable 2023 history unavailable');else if(c.market.boomExcess>=0)reasons.push('Already ahead of benchmark since 2023')}return reasons}
function scenarioNote(c,i=scenarioIndex){const p=scenariosData.profiles[c.ticker];if(p.scenarioNotes.length)return p.scenarioNotes[i];const generic=[
 'In a sustained buildout, direct infrastructure demand matters most; indirect exposure and weak cash capture can leave a company behind.',
 'As AI gets cheaper, adoption and pricing power matter more than raw compute volume; commoditisation can offset higher usage.',
 'During a funding and deployment reset, cash conversion and existing customer demand matter more than announced capacity or backlog.'
];return p.scores[i]<0?p.risk+' '+generic[i]:p.mechanism+' '+generic[i]}
function scenarioMarketText(c){const m=c.market;return m?`1 year: ${pct(m.return1y)} stock · ${m.excess>0?'+':''}${m.excess.toFixed(1)} pp vs ${m.benchmark}. ${m.boomComparable?'Since 2023: '+pct(m.boomReturn)+' stock · '+(m.boomExcess>0?'+':'')+m.boomExcess.toFixed(1)+' pp.':'2023 comparison limited.'}`:'Price comparison unavailable'}
function sourceLink(id){const s=scenariosData.sources[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`}
function scenarioCard(c,kind){const p=scenariosData.profiles[c.ticker],n=scenarioRating(c);return `<article class="thesis-card ${kind}"><div class="thesis-top"><span class="eyebrow">${esc(c.ticker)}</span>${ratingMarkup(n)}</div><button data-company="${esc(c.ticker)}" class="thesis-title">${esc(c.name)}</button><p>${esc(scenarioNote(c))}</p><div class="thesis-market">${esc(scenarioMarketText(c))}</div><p class="thesis-fundamentals">Revenue growth ${pct(c.revenueGrowth)} · net ${money(val(c,'net'),c.currency)} · FCF ${money(val(c,'fcf'),c.currency)}<br>${esc(c.basis)} to ${date(c.end)}</p><p class="thesis-risk"><b>What could go wrong</b> ${esc(p.risk)}</p>${c.stale?'<p class="old">Older financial period: not eligible for the hidden-champion screen.</p>':''}<button class="thesis-open" data-company="${esc(c.ticker)}">Examine thesis & financials</button></article>`}
function curveSvg(){const list=scenariosData.scenarios,x=i=>60+180*i,y=v=>235-(v-50)*1.0;let s='<svg viewBox="0 0 850 290" role="img" aria-label="Three illustrative infrastructure spending paths, 2026 equals 100. These are assumptions, not forecasts.">';for(const n of [75,100,150,200,250])s+=`<line x1="55" x2="790" y1="${y(n)}" y2="${y(n)}" stroke="#dce4ed" stroke-dasharray="${n===100?'0':'3 5'}"/><text x="43" y="${y(n)+4}" text-anchor="end" fill="#677486" font-size="12">${n}</text>`;list.forEach((a,i)=>{s+=`<path d="${a.path.map((v,k)=>(k?'L':'M')+x(k)+' '+y(v)).join(' ')}" fill="none" stroke="${a.color}" stroke-width="${i===scenarioIndex?4:2}" opacity="${i===scenarioIndex?1:.45}"/>`;if(i===scenarioIndex)a.path.forEach((v,k)=>s+=`<circle cx="${x(k)}" cy="${y(v)}" r="4" fill="${a.color}"/><text x="${x(k)}" y="${y(v)-12}" text-anchor="middle" font-size="12" fill="${a.color}">${v}</text>`)});for(let i=0;i<5;i++)s+=`<text x="${x(i)}" y="271" text-anchor="middle" fill="#677486" font-size="12">${2026+i}</text>`;return s+'</svg>'}
function initScenarios(){
 $('#scenario-sector').innerHTML='<option value="">All supply-chain layers</option>'+Object.keys(colors).map(s=>`<option>${esc(s)}</option>`).join('');
 $('#scenario-query').oninput=e=>{scenarioQuery=e.target.value;renderScenarioTable()};
 $('#scenario-sector').onchange=e=>{scenarioSector=e.target.value;renderScenarioTable()};
 $('#scenario-focus').onchange=e=>{scenarioFocus=e.target.value;renderScenarioTable()};
 $('#scenario-window').onchange=e=>{recognitionWindow=e.target.value;renderScenarios()};
 $('#scenario-gap').onchange=e=>{recognitionGap=Number(e.target.value);renderScenarios()};
 $('#scenario-reset').onclick=()=>{scenarioFocus='all';scenarioQuery='';scenarioSector='';recognitionGap=0;recognitionWindow='both';$('#scenario-window').value='both';$('#scenario-query').value='';$('#scenario-sector').value='';$('#scenario-focus').value='all';$('#scenario-gap').value='0';renderScenarios()};
 renderScenarios();
}
function renderScenarios(){if(!scenariosData)return;const s=currentScenario();
 $('#scenario-tabs').innerHTML=scenariosData.scenarios.map((a,i)=>`<button class="scenario-tab ${scenarioIndex===i?'selected':''}" data-scenario="${i}" aria-pressed="${scenarioIndex===i}" style="--accent:${a.color}"><span>${a.number} / ${esc(a.short.toUpperCase())}</span><strong>${esc(a.name)}</strong><small>${esc(a.tagline)}</small></button>`).join('');
 $('#scenario-tabs').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{scenarioIndex=Number(b.dataset.scenario);renderScenarios()}));
 $('#scenario-summary').innerHTML=`<div class="scenario-brief"><span class="eyebrow">IF THIS WORLD MATERIALISES</span><h3>${esc(s.tagline)}</h3><p>${esc(s.summary)}</p><p class="scenario-boundary">${esc(s.risk)}</p></div><div class="scenario-assumptions">${s.assumptions.map(([k,v])=>`<div><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('')}</div>`;
 $('#scenario-path').innerHTML=curveSvg();$('#scenario-path-legend').innerHTML=scenariosData.scenarios.map(a=>`<span><i style="background:${a.color}"></i>${esc(a.short)}</span>`).join('');
 $('#scenario-timeline').innerHTML=s.timing.map(([year,text])=>`<div><b>${esc(year)}</b><p>${esc(text)}</p></div>`).join('');
 $('#scenario-signals').innerHTML=`<article><h3>Evidence that would support this world</h3><ul>${s.watch.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article><article><h3>What would change the conclusion</h3><p>${esc(s.invalidate)}</p><p class="small">These are research signposts, not live alerts. Reassess after results and major changes in financing, power availability or model economics.</p></article>`;
 $('#scenario-winners').innerHTML=s.winners.map(t=>scenarioCard(companies.find(c=>c.ticker===t),'winner')).join('');
 $('#scenario-losers').innerHTML=s.losers.map(t=>scenarioCard(companies.find(c=>c.ticker===t),'loser')).join('');
 const hidden=companies.filter(c=>hiddenInScenario(c));const order=t=>s.hiddenPriority.includes(t)?s.hiddenPriority.indexOf(t):999;
 hidden.sort((a,b)=>order(a.ticker)-order(b.ticker)||scenarioRating(b)-scenarioRating(a)||a.market.excess-b.market.excess);
 $('#scenario-hidden-count').textContent=hidden.length+' companies pass in '+s.short+' · '+(recognitionWindow==='both'?'both stock windows':'recent laggards');
 $('#scenario-hidden').innerHTML=hidden.length?hidden.slice(0,6).map(c=>scenarioCard(c,'hidden-candidate')).join(''):'<div class="no-scenario-results">No company clears every gate for this scenario and recognition threshold. A missing candidate is more useful than forcing a pick. Use the comparison below to inspect near misses.</div>';
 $('#scenario-hidden-note').textContent=hidden.length>6?`Showing 6 editorial priorities from ${hidden.length} qualifying companies. Select “Hidden-champion candidates” below to inspect every match.`:'All qualifying companies are shown above. These are benchmark laggards, not proven bargains or measurements of investor awareness.';
 bindCompanies($('#scenarios-view'));renderScenarioTable();
}
function scenarioFiltered(){return companies.filter(c=>{const n=scenarioRating(c),p=scenariosData.profiles[c.ticker];return (!scenarioQuery||(c.name+' '+c.ticker+' '+c.role).toLowerCase().includes(scenarioQuery.toLowerCase()))&&(!scenarioSector||c.sector===scenarioSector)&&(scenarioFocus==='all'||scenarioFocus==='hidden'&&hiddenInScenario(c)||scenarioFocus==='winners'&&n>=2||scenarioFocus==='losers'&&n<=-2||scenarioFocus==='resilient'&&p.scores.every(n=>n>=1)||scenarioFocus==='laggards'&&c.market&&c.market.excess<recognitionGap||scenarioFocus==='incomplete'&&(c.stale||val(c,'fcf')==null||c.revenueGrowth==null||!c.market?.boomComparable))})}
function renderScenarioTable(){if(!scenariosData)return;const rows=scenarioFiltered().sort((a,b)=>scenarioRating(b)-scenarioRating(a)||a.name.localeCompare(b.name));$('#scenario-count').textContent=`${rows.length} of 100 companies · sorted by ${currentScenario().short.toLowerCase()} positioning, then name`;$('#scenario-rows').innerHTML=rows.map(c=>{const p=scenariosData.profiles[c.ticker],h=hiddenInScenario(c);return `<tr><td><button class="name-button" data-company="${esc(c.ticker)}">${esc(c.name)}</button><span class="company-ticker">${esc(c.ticker)}</span><small>${esc(c.sector)}</small></td>${p.scores.map((n,i)=>`<td class="${i===scenarioIndex?'chosen-scenario':''}">${ratingMarkup(n)}</td>`).join('')}<td class="${sign(c.market?.excess)}">${c.market?(c.market.excess>0?'+':'')+c.market.excess.toFixed(1)+' pp':'—'}<small>${pct(c.market?.return1y??null)} stock · 1 year</small><small>${c.market?.boomComparable?'Since 2023: '+(c.market.boomExcess>0?'+':'')+c.market.boomExcess.toFixed(1)+' pp':'2023 window not comparable'}</small></td><td>${h?'<span class="positive"><b>Candidate</b></span>':esc(hiddenFailures(c)[0])}<small>${c.stale?'Older period':c.basis+' · '+date(c.end)}${h?' · valuation not checked':''}</small></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No companies match. Reset the filters or reduce the benchmark-gap requirement.</td></tr>';bindCompanies($('#scenario-rows'))}
function scenarioDetail(c){if(!scenariosData)return '';const p=scenariosData.profiles[c.ticker],reasons=hiddenFailures(c);return `<section class="detail-scenarios"><span class="eyebrow">2026–2030 / CONDITIONAL ANALYSIS</span><h3>Three possible futures for ${esc(c.name)}</h3><p class="mini-label">Editorial business-position ratings. These are neither forecast stock returns nor probabilities.</p>${scenariosData.scenarios.map((s,i)=>`<article class="detail-scenario"><div><b>${esc(s.short)}</b>${ratingMarkup(p.scores[i])}</div><p>${esc(scenarioNote(c,i))}</p></article>`).join('')}<h3>Hidden-champion decision · ${esc(currentScenario().short)}</h3><p class="note">${!reasons.length?'Passes the financial, scenario and relative-stock gates. Valuation and investor awareness are not established.':esc(reasons.join(' · '))+'.'}</p><p><b>Business channel:</b> ${esc(p.mechanism)}</p><p><b>Main counterargument:</b> ${esc(p.risk)}</p><p><b>Next evidence to watch:</b> ${esc(p.watch)}</p><p class="mini-label">Thesis basis: ${esc(p.evidenceLevel)}. Financial statements and market data are shown separately below.</p>${p.sources.length?'<div class="sources">'+p.sources.map(sourceLink).join('')+'</div>':'<p class="mini-label">This company’s scenario assessment is a qualitative inference from its business role, not a sourced issuer forecast. Check the linked financial filings before relying on the thesis.</p>'}</section>`}
